import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class AssetLookupServlet extends HttpServlet {
    private static final Logger logger = Logger.getLogger(AssetLookupServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String assetTag = req.getParameter("tag");
        String department = req.getParameter("dept");

        if (assetTag == null || department == null) {
            resp.sendError(400, "Missing parameters");
            return;
        }

        // Validate department against known list
        String[] validDepts = {"engineering", "finance", "hr", "operations", "legal"};
        boolean validDept = false;
        for (String d : validDepts) {
            if (d.equals(department)) { validDept = true; break; }
        }
        if (!validDept) {
            resp.sendError(400, "Invalid department");
            return;
        }

        // Length check on asset tag - seems like input validation but insufficient
        if (assetTag.length() > 200) {
            resp.sendError(400, "Tag too long");
            return;
        }

        resp.setContentType("application/json");
        PrintWriter out = resp.getWriter();

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            // VULNERABLE: String concatenation in SQL query
            String query = "SELECT asset_id, asset_name, location, status FROM assets "
                         + "WHERE asset_tag = '" + assetTag + "' "
                         + "AND department = '" + department + "'";

            logger.info("Executing asset lookup for dept=" + department);

            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(query);

            StringBuilder json = new StringBuilder("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) json.append(",\n");
                json.append("  {\"id\": ").append(rs.getInt("asset_id"))
                    .append(", \"name\": \"").append(rs.getString("asset_name"))
                    .append("\", \"location\": \"").append(rs.getString("location"))
                    .append("\", \"status\": \"").append(rs.getString("status"))
                    .append("\"}");
                first = false;
            }
            json.append("\n]");
            out.print(json.toString());
        } catch (SQLException e) {
            logger.warning("DB error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // POST delegates to GET for backward compat
        doGet(req, resp);
    }
}
